import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.kOe0DhAP.js";const _=JSON.parse('{"title":"功能全景","description":"从用户交易到平台运营，认识业务模块之间的关系。","frontmatter":{"title":"功能全景","description":"从用户交易到平台运营，认识业务模块之间的关系。"},"headers":[],"relativePath":"00/0002/000002.md","filePath":"00/0002/000002.md"}'),o={name:"00/0002/000002.md"};function n(c,t,i,s,l,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<div class="doc-eyebrow">项目介绍 / TGEX KNOWLEDGE BASE</div><h1 id="功能全景" tabindex="-1">功能全景 <a class="header-anchor" href="#功能全景" aria-label="Permalink to &quot;功能全景&quot;">​</a></h1><div class="doc-lead">从用户交易到平台运营，认识业务模块之间的关系。</div><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务域</th><th>主要职责</th><th>工程对应</th></tr></thead><tbody><tr><td>用户</td><td>身份、登录、认证与用户关系</td><td>coinex-user、coinex-user-relation</td></tr><tr><td>账务</td><td>资产账户、余额与资金变动</td><td>coinex-account</td></tr><tr><td>现货</td><td>委托、现货撮合与行情</td><td>coinex-entrust、coinex-match、coinex-market</td></tr><tr><td>合约</td><td>合约委托、撮合与行情</td><td>coinex-contract-entrust、coinex-contract-match、coinex-contract-market</td></tr><tr><td>期权</td><td>周期、方向、订单与结算</td><td>coinex-contract-option-*</td></tr><tr><td>钱包</td><td>链上地址、转账与归集</td><td>coinex-wallet</td></tr><tr><td>OTC</td><td>广告委托、订单、商家与申诉</td><td>coinex-otc</td></tr></tbody></table><h2 id="支撑业务" tabindex="-1">支撑业务 <a class="header-anchor" href="#支撑业务" aria-label="Permalink to &quot;支撑业务&quot;">​</a></h2><p>商户相关能力由 coinex-partner、coinex-partner-admin 等模块承载。机器人、量化、活动、奖励、报表分别可以在 coinex-robot、coinex-quantize、coinex-activity、coinex-raward、coinex-report 中找到对应实现。</p><p>模块清单说明的是工程组织方式。一个用户动作往往需要多个模块共同完成，不能把某个目录理解为完整独立的业务闭环。</p>',8)])])}const p=e(o,[["render",n]]);export{_ as __pageData,p as default};
